const items = [
  {id:'credo-ai', name:'Credo AI'},
  {id:'holistic-ai', name:'Holistic AI'},
  {id:'trustible', name:'Trustible'},
  {id:'enzai', name:'Enzai'},
  {id:'saidot', name:'Saidot'},
  {id:'lumenova-ai', name:'Lumenova AI'},
  {id:'monitaur', name:'Monitaur'},
  {id:'asenion', name:'Asenion'},
  {id:'verifywise', name:'VerifyWise'}
];
const schema = JSON.stringify({type:'object',properties:{id:{type:'string'},name:{type:'string'},official_summary:{type:'string'},capabilities:{type:'array',items:{type:'string'}},deployment_claims:{type:'array',items:{type:'string'}},ai_governance_scope:{type:'array',items:{type:'string'}},commercial_evidence:{type:'array',items:{type:'string'}},official_sources:{type:'array',items:{type:'string'}},evidence_quality:{type:'string'},limitations:{type:'string'}},required:['id','name','official_summary','capabilities','deployment_claims','ai_governance_scope','commercial_evidence','official_sources','evidence_quality','limitations']});
const mapped = await parallel('بحث المنصات التسع رسميًا', () => items.map(item => agent(
  'Research exactly this competitor: ' + item.name + '. Use only the company’s official public website, official product documentation, official blog/press pages, or its official source repository if applicable. Search and open multiple relevant sources; do not rely on snippets. Report only publicly stated capabilities and clearly distinguish them from functions actually verified (do not claim you tested the software). Assess inventory/registry, policy packs, agents, evaluation, monitoring, enforcement, evidence/audit, and deployment only where official sources support it. Note pricing/commercial evidence only if an official public source says so. Include at least 2 direct official URLs when available, access-current findings cautiously, and state unknowns; do not infer superiority or market share. Return concise Arabic values for: id=' + item.id + ', name, official_summary, capabilities, deployment_claims, ai_governance_scope, commercial_evidence, official_sources, evidence_quality, limitations. No file output required.',
  {brief:'بحث مصدر رسمي: ' + item.name,sandbox:'isolated',effort_level:'lite',schema}
)), {schema});
const successful = mapped.filter(r => r.ok).map(r => r.value);
const failures = mapped.map((r,i) => r.ok ? null : {id:items[i].id,code:r.error.code,message:r.error.message}).filter(Boolean);
const reducer = await agent('Synthesize these nine official-source competitor results into a concise Arabic comparison suitable for an audit report. Preserve only claims supported by returned official URLs; do not claim AIGAS superiority. Return a structured comparison: table_rows (one per successful competitor, each with competitor, supported_capabilities, deployment, explicit_unknowns, official_sources), cross_competitor_patterns, evidence_gaps, and selection_test_for_AIGAS. Inputs:\n' + JSON.stringify({successful,failures}), {brief:'تلخيص مقارنة المنافسين بمصادرها',sandbox:'isolated',effort_level:'standard',schema:JSON.stringify({type:'object',properties:{table_rows:{type:'array',items:{type:'object',properties:{competitor:{type:'string'},supported_capabilities:{type:'array',items:{type:'string'}},deployment:{type:'array',items:{type:'string'}},explicit_unknowns:{type:'array',items:{type:'string'}},official_sources:{type:'array',items:{type:'string'}}},required:['competitor','supported_capabilities','deployment','explicit_unknowns','official_sources']}},cross_competitor_patterns:{type:'array',items:{type:'string'}},evidence_gaps:{type:'array',items:{type:'string'}},selection_test_for_AIGAS:{type:'array',items:{type:'string'}}},required:['table_rows','cross_competitor_patterns','evidence_gaps','selection_test_for_AIGAS']})});
return {successful,failures,synthesis:reducer.ok?reducer.value:null,reducer_failure:reducer.ok?null:reducer.error};

